<script setup lang="ts">
const { lines, subtotal, setQuantity, remove, clear } = useCart()
const completed = ref(false)
const money = (cents: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(cents / 100)
function mockCheckout() { if (!lines.value.length) return; clear(); completed.value = true }
useShopSeo('Your shopping cart', 'Review the items in your ARC Studio demonstration shopping cart. No payment is collected.', '/cart')
useSeoMeta({ robots: 'noindex, nofollow' })
</script>
<template>
  <div class="shell pb-28 pt-14 sm:pt-20">
    <p class="eyebrow">Your edit</p><h1 class="mt-2 font-display text-[clamp(2.8rem,5.5vw,5.3rem)] font-extrabold tracking-[-.07em]">The cart<span class="text-coral">.</span></h1>
    <div v-if="completed" role="status" class="mt-10 rounded-[25px] bg-[#e1e7dd] p-12 text-center"><p class="text-4xl">✓</p><h2 class="mt-5 font-display text-3xl font-bold">Demo order complete.</h2><p class="mt-4 text-muted">This was a simulated checkout. No payment was taken, and no real order was created.</p><NuxtLink to="/products" class="button-dark mt-7">Continue shopping ↗</NuxtLink></div>
    <div v-else-if="!lines.length" class="mt-12 rounded-[24px] border border-line bg-white px-8 py-20 text-center"><h2 class="font-display text-2xl font-bold">Your cart is taking a breather.</h2><p class="mt-3 text-muted">Good things come to those who browse.</p><NuxtLink to="/products" class="button-dark mt-7">Discover the collection ↗</NuxtLink></div>
    <div v-else class="mt-12 grid gap-12 lg:grid-cols-[1fr_350px]"><div class="space-y-6"><article v-for="line in lines" :key="line.product.slug" class="grid grid-cols-[110px_1fr] gap-5 border-b border-line pb-6 sm:grid-cols-[160px_1fr]"><NuxtLink :to="`/products/${line.product.slug}`" class="grid aspect-square place-items-center rounded-[20px] bg-[#e5e5de]"><img :src="line.product.image" :alt="line.product.name" width="200" height="200" loading="lazy" class="h-full w-full object-contain p-2" /></NuxtLink><div class="flex flex-col justify-between gap-4"><div><p class="eyebrow">{{ line.product.category }}</p><NuxtLink :to="`/products/${line.product.slug}`" class="mt-2 block font-display text-lg font-bold hover:underline">{{ line.product.name }}</NuxtLink><p class="mt-2 text-sm font-bold">{{ money(line.product.price) }}</p></div><div class="flex flex-wrap items-center gap-4"><div class="inline-flex items-center rounded-full border border-line bg-white" :aria-label="`Quantity for ${line.product.name}`"><button type="button" class="px-4 py-2" :aria-label="`Decrease ${line.product.name} quantity`" @click="setQuantity(line.product.slug, line.quantity - 1)">−</button><span class="min-w-5 text-center text-sm">{{ line.quantity }}</span><button type="button" class="px-4 py-2" :disabled="line.quantity >= line.product.inventory" :aria-label="`Increase ${line.product.name} quantity`" @click="setQuantity(line.product.slug, line.quantity + 1)">+</button></div><button type="button" @click="remove(line.product.slug)" class="text-xs text-muted underline underline-offset-4 hover:text-coral">Remove</button></div></div></article></div><aside class="h-fit rounded-[24px] bg-white p-7 sm:p-9"><h2 class="font-display text-xl font-bold">Order summary</h2><div class="mt-7 flex justify-between border-b border-line pb-5 text-sm"><span>Subtotal</span><strong>{{ money(subtotal) }}</strong></div><p class="mt-5 text-xs leading-6 text-muted">Taxes and delivery are intentionally not calculated in this demonstration.</p><button type="button" @click="mockCheckout" class="button-dark mt-8 w-full">Complete mock checkout ↗</button><p class="mt-3 text-center text-xs text-muted">No payment details required.</p></aside></div>
  </div>
</template>
